cd /home/exedev/shipshape-shakedown/.eval-scratch/P4-cand-hy3/sim && node -e '
const fs = require("fs");
const wb = JSON.parse(fs.readFileSync("watchbill.json","utf8"));
const feat = fs.readFileSync("features/todomvc.feature","utf8");
const names = new Set();
for (const line of feat.split("\n")) {
  const m = line.match(/^(  )?(Scenario Outline|Scenario): (.+)$/);
  if (m) names.add(m[3].trim());
}
let total=0, missing=[];
for (const [w,obj] of Object.entries(wb)) {
  for (const ref of obj.scenarios) {
    total++;
    const name = ref.split(":").slice(1).join(":").trim();
    if (!names.has(name)) missing.push(ref);
  }
}
console.log("watchbill JSON valid. references:", total);
console.log("scenario defs in spec:", names.size);
console.log("unmatched references:", missing.length ? missing : "none");
'
